public class LFUCache {
    private sealed class Entry { public int val, freq = 1; public LinkedListNode<int> node; }

    private readonly int capacity;
    private readonly Dictionary<int, Entry> map = new();
    private readonly Dictionary<int, LinkedList<int>> buckets = new();   // freq → ключи, давний первым
    private int minFreq;

    public LFUCache(int capacity) => this.capacity = capacity;

    public int Get(int key) {
        if (!map.TryGetValue(key, out var e)) return -1;
        Touch(e);
        return e.val;
    }

    public void Put(int key, int value) {
        if (capacity == 0) return;
        if (map.TryGetValue(key, out var e)) {
            e.val = value;
            Touch(e);                              // Put — тоже обращение
            return;
        }
        if (map.Count == capacity) {
            var victims = buckets[minFreq];        // самые редкие, давний первым
            map.Remove(victims.First.Value);       // ничья — по давности
            victims.RemoveFirst();
        }
        minFreq = 1;                               // новый ключ всегда самый редкий
        map[key] = new Entry { val = value, node = Bucket(1).AddLast(key) };
    }

    private void Touch(Entry e) {
        var from = buckets[e.freq];
        from.Remove(e.node);                       // O(1): узел в руках
        if (from.Count == 0 && minFreq == e.freq) minFreq++;   // опустела нижняя корзина
        e.freq++;
        Bucket(e.freq).AddLast(e.node);            // тот же узел переезжает: без новой аллокации
    }

    private LinkedList<int> Bucket(int freq) {
        if (!buckets.TryGetValue(freq, out var list)) buckets[freq] = list = new LinkedList<int>();
        return list;
    }
}

