// Старение: счётчики пополам. O(n), но редко — при смене уровня или раз в N операций
void Age() {
    var old = buckets.OrderBy(b => b.Key).ToList();   // корзины по возрастанию частоты
    buckets.Clear();
    minFreq = int.MaxValue;
    foreach (var (f, list) in old)
        foreach (int key in list) {                   // в корзине — от давнего к свежему
            var e = map[key];
            e.freq = Math.Max(1, f / 2);
            e.node = Bucket(e.freq).AddLast(key);
            minFreq = Math.Min(minFreq, e.freq);
        }
}
